sealed class VoiceOptions {
 public string Backend="flash",ApiKey="",AppKey="",AccessKey="",ResourceId="volc.bigasr.auc_turbo",Endpoint="https://openspeech.bytedance.com/api/v3/auc/bigmodel/recognize/flash";
 public bool HoldMode,SaveHistory=true;public int RetentionDays=30,MaxSeconds=300;public uint Modifiers=HotkeyGesture.Control|HotkeyGesture.Alt;public int VirtualKey=0x20;
 public bool Ready {get{return (!string.IsNullOrWhiteSpace(ApiKey)||(!string.IsNullOrWhiteSpace(AppKey)&&!string.IsNullOrWhiteSpace(AccessKey)))&&!string.IsNullOrWhiteSpace(ResourceId);}}
 public HotkeyGesture Gesture {get{return new HotkeyGesture(Modifiers,VirtualKey);}}
}

sealed class VoiceTerm {public string word="";public List<string> aliases=new List<string>();public bool enabled=true;public string source="manual";public string createdAt="",updatedAt="";}
sealed class VoiceHistoryItem {public string id="",createdAt="",text="",status="final";}
sealed class VoiceBackup {public int schemaVersion=1;public List<VoiceTerm> terms=new List<VoiceTerm>();}

static class VoiceData {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};
 public static string Root {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BanaStudio");}}
 static string LegacyRoot {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Banarec");}}
 public static void EnsureMigrated(){Directory.CreateDirectory(Root);string marker=Path.Combine(Root,".migrated-v3");if(File.Exists(marker))return;foreach(string name in new[]{"settings.ini"}){string old=Path.Combine(LegacyRoot,name),now=Path.Combine(Root,name);if(File.Exists(old)&&!File.Exists(now))File.Copy(old,now);}File.WriteAllText(marker,DateTime.UtcNow.ToString("o"),Encoding.UTF8);}
 static string Protect(string value){if(string.IsNullOrEmpty(value))return "";return Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(value),null,DataProtectionScope.CurrentUser));}
 static string Unprotect(string value){if(string.IsNullOrEmpty(value))return "";try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(value),null,DataProtectionScope.CurrentUser));}catch{return "";}}
 public static VoiceOptions LoadOptions(){EnsureMigrated();string p=Path.Combine(Root,"voice-settings.json");try{var map=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));var o=new VoiceOptions();o.Backend=Get(map,"backend",o.Backend);o.ApiKey=Unprotect(Get(map,"apiKey"));o.AppKey=Unprotect(Get(map,"appKey"));o.AccessKey=Unprotect(Get(map,"accessKey"));o.ResourceId=Get(map,"resourceId",o.ResourceId);o.Endpoint=Get(map,"endpoint",o.Endpoint);o.HoldMode=Bool(map,"holdMode");o.SaveHistory=!map.ContainsKey("saveHistory")||Bool(map,"saveHistory");o.RetentionDays=Int(map,"retentionDays",30);o.MaxSeconds=Int(map,"maxSeconds",300);o.Modifiers=(uint)Int(map,"modifiers",(int)o.Modifiers);o.VirtualKey=Int(map,"virtualKey",o.VirtualKey);return o;}catch{return new VoiceOptions();}}
 public static void SaveOptions(VoiceOptions o){EnsureMigrated();var map=new Dictionary<string,object>{{"schemaVersion",1},{"backend",o.Backend},{"apiKey",Protect(o.ApiKey)},{"appKey",Protect(o.AppKey)},{"accessKey",Protect(o.AccessKey)},{"resourceId",o.ResourceId},{"endpoint",o.Endpoint},{"holdMode",o.HoldMode},{"saveHistory",o.SaveHistory},{"retentionDays",o.RetentionDays},{"maxSeconds",o.MaxSeconds},{"modifiers",o.Modifiers},{"virtualKey",o.VirtualKey}};Atomic(Path.Combine(Root,"voice-settings.json"),Json.Serialize(map));}
 static string Get(Dictionary<string,object> m,string k,string d=""){object v;return m.TryGetValue(k,out v)&&v!=null?Convert.ToString(v):d;}static bool Bool(Dictionary<string,object> m,string k){object v;return m.TryGetValue(k,out v)&&Convert.ToBoolean(v);}static int Int(Dictionary<string,object> m,string k,int d){object v;int n;return m.TryGetValue(k,out v)&&int.TryParse(Convert.ToString(v),out n)?n:d;}
 public static List<VoiceTerm> LoadTerms(){EnsureMigrated();try{var b=Json.Deserialize<VoiceBackup>(File.ReadAllText(Path.Combine(Root,"dictionary.json"),Encoding.UTF8));return b!=null&&b.terms!=null?b.terms:new List<VoiceTerm>();}catch{return new List<VoiceTerm>();}}
 public static void SaveTerms(IEnumerable<VoiceTerm> terms){Atomic(Path.Combine(Root,"dictionary.json"),Json.Serialize(new VoiceBackup{terms=terms.ToList()}));}
 public static List<VoiceHistoryItem> LoadHistory(){EnsureMigrated();try{return Json.Deserialize<List<VoiceHistoryItem>>(File.ReadAllText(Path.Combine(Root,"history.json"),Encoding.UTF8))??new List<VoiceHistoryItem>();}catch{return new List<VoiceHistoryItem>();}}
 public static void AddHistory(string text,string status,VoiceOptions options){if(!options.SaveHistory||string.IsNullOrWhiteSpace(text))return;var all=LoadHistory();DateTime cutoff=DateTime.UtcNow.AddDays(-Math.Max(1,options.RetentionDays));all=all.Where(x=>{DateTime d;return DateTime.TryParse(x.createdAt,out d)&&d>=cutoff;}).Take(499).ToList();all.Insert(0,new VoiceHistoryItem{id=Guid.NewGuid().ToString("N"),createdAt=DateTime.UtcNow.ToString("o"),text=text,status=status});Atomic(Path.Combine(Root,"history.json"),Json.Serialize(all));}
 public static void ClearHistory(){Atomic(Path.Combine(Root,"history.json"),"[]");}
 public static void ExportJson(string path,IEnumerable<VoiceTerm> terms){File.WriteAllText(path,Json.Serialize(new VoiceBackup{terms=terms.ToList()}),new UTF8Encoding(false));}
 public static List<VoiceTerm> Import(string path){var file=new FileInfo(path);if(!file.Exists)throw new FileNotFoundException("词库文件不存在。",path);if(file.Length>4*1024*1024)throw new InvalidDataException("词库文件不能超过 4 MB。");string ext=Path.GetExtension(path).ToLowerInvariant(),data=File.ReadAllText(path,Encoding.UTF8);List<VoiceTerm> found;if(ext==".json"){var shape=Json.DeserializeObject(data) as Dictionary<string,object>;if(shape==null||!shape.ContainsKey("terms"))throw new InvalidDataException("词库 JSON 缺少 terms。");var b=Json.Deserialize<VoiceBackup>(data);if(b==null||b.schemaVersion!=1||b.terms==null)throw new InvalidDataException("不支持的词库 JSON 格式。");found=b.terms;}else if(ext==".txt")found=data.Split(new[]{"\r\n","\n"},StringSplitOptions.None).Select(x=>NewTerm(x.Trim(),new List<string>(),"import")).ToList();else if(ext==".csv")found=ParseCsv(data);else throw new InvalidDataException("仅支持 JSON、CSV 或 TXT。");return Validate(found);}
 static List<VoiceTerm> ParseCsv(string s){var rows=new List<List<string>>();var row=new List<string>();var cell=new StringBuilder();bool quote=false;for(int i=0;i<s.Length;i++){char c=s[i];if(quote){if(c=='"'&&i+1<s.Length&&s[i+1]=='"'){cell.Append('"');i++;}else if(c=='"')quote=false;else cell.Append(c);}else if(c=='"')quote=true;else if(c==','){row.Add(cell.ToString());cell.Clear();}else if(c=='\r'){}else if(c=='\n'){row.Add(cell.ToString());cell.Clear();rows.Add(row);row=new List<string>();}else cell.Append(c);}if(quote)throw new InvalidDataException("CSV 引号未闭合。");if(cell.Length>0||row.Count>0){row.Add(cell.ToString());rows.Add(row);}if(rows.Count==0)return new List<VoiceTerm>();int wi=0,ai=-1,ei=-1,start=0;var head=rows[0].Select(x=>x.Trim().ToLowerInvariant()).ToList();if(head.Contains("word")){wi=head.IndexOf("word");ai=head.IndexOf("aliases");ei=head.IndexOf("enabled");start=1;}var list=new List<VoiceTerm>();for(int i=start;i<rows.Count;i++){var r=rows[i];string word=wi<r.Count?CsvImported(r[wi].Trim()):"";var aliases=ai>=0&&ai<r.Count?CsvImported(r[ai]).Split(new[]{'|',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToList():new List<string>();var t=NewTerm(word,aliases,"import");if(ei>=0&&ei<r.Count){bool v;if(bool.TryParse(r[ei],out v))t.enabled=v;}list.Add(t);}return list;}
 public static void ExportCsv(string path,IEnumerable<VoiceTerm> terms){var b=new StringBuilder("word,aliases,enabled\r\n");foreach(var t in terms)b.Append(Csv(t.word)).Append(',').Append(Csv(string.Join("|",t.aliases??new List<string>()))).Append(',').Append(t.enabled?"true":"false").Append("\r\n");File.WriteAllText(path,b.ToString(),new UTF8Encoding(true));}
 static string Csv(string v){v=v??"";if(v.Length>0&&(v[0]=='='||v[0]=='+'||v[0]=='-'||v[0]=='@'))v="'"+v;return '"'+v.Replace("\"","\"\"")+'"';}
 static string CsvImported(string value){return value!=null&&value.Length>1&&value[0]=='\''&&(value[1]=='='||value[1]=='+'||value[1]=='-'||value[1]=='@')?value.Substring(1):value;}
 public static VoiceTerm NewTerm(string word,List<string> aliases,string source){string now=DateTime.UtcNow.ToString("o");return new VoiceTerm{word=word,aliases=aliases,source=source,createdAt=now,updatedAt=now};}
 static List<VoiceTerm> Validate(IEnumerable<VoiceTerm> input){var result=new List<VoiceTerm>();var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var t in input){if(t==null)continue;t.word=(t.word??"").Trim();if(t.word.Length==0)continue;if(t.word.Length>100)throw new InvalidDataException("词语长度不能超过 100 个字符。");if(!seen.Add(t.word))continue;t.aliases=(t.aliases??new List<string>()).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x.Trim()).Distinct(StringComparer.Ordinal).Take(20).ToList();if(string.IsNullOrEmpty(t.createdAt))t.createdAt=DateTime.UtcNow.ToString("o");t.updatedAt=DateTime.UtcNow.ToString("o");result.Add(t);if(result.Count>5000)throw new InvalidDataException("词库最多 5000 条。");}return result;}
 public static List<VoiceTerm> Merge(IEnumerable<VoiceTerm> current,IEnumerable<VoiceTerm> incoming){var all=Validate(current??new VoiceTerm[0]).ToDictionary(x=>x.word,StringComparer.Ordinal);foreach(var t in Validate(incoming)){VoiceTerm old;if(all.TryGetValue(t.word,out old)){old.aliases=(old.aliases??new List<string>()).Concat(t.aliases??new List<string>()).Distinct(StringComparer.Ordinal).Take(20).ToList();old.enabled=t.enabled;old.updatedAt=DateTime.UtcNow.ToString("o");}else{if(all.Count>=5000)throw new InvalidDataException("词库最多 5000 条。");all.Add(t.word,t);}}return Validate(all.Values).OrderBy(x=>x.word,StringComparer.CurrentCulture).ToList();}
 static void Atomic(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));string tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(tmp,text,new UTF8Encoding(false));if(File.Exists(path)){string bak=path+".bak";File.Replace(tmp,path,bak,true);}else File.Move(tmp,path);}
}

sealed class DoubaoAsrClient:IDisposable {
 readonly VoiceOptions options;readonly List<string> hotwords;ClientWebSocket socket;CancellationTokenSource stop;Task receive;public event Action<string,bool> Text;public event Action<string> Failed;
 public DoubaoAsrClient(VoiceOptions o,IEnumerable<string> words){options=o;hotwords=words.Where(x=>!string.IsNullOrWhiteSpace(x)).Take(1000).ToList();}
 public async Task Connect(CancellationToken token){socket=new ClientWebSocket();if(!string.IsNullOrWhiteSpace(options.ApiKey))socket.Options.SetRequestHeader("X-Api-Key",options.ApiKey);else{socket.Options.SetRequestHeader("X-Api-App-Key",options.AppKey);socket.Options.SetRequestHeader("X-Api-Access-Key",options.AccessKey);}socket.Options.SetRequestHeader("X-Api-Resource-Id",options.ResourceId);socket.Options.SetRequestHeader("X-Api-Request-Id",Guid.NewGuid().ToString());socket.Options.SetRequestHeader("X-Api-Connect-Id",Guid.NewGuid().ToString());socket.Options.SetRequestHeader("X-Api-Sequence","-1");await socket.ConnectAsync(new Uri(options.Endpoint),token);stop=CancellationTokenSource.CreateLinkedTokenSource(token);receive=Receive(stop.Token);await SendRequest(stop.Token);}
