 async Task Send(byte[] data,CancellationToken t){if(socket==null||socket.State!=WebSocketState.Open)throw new InvalidOperationException("识别连接未打开。");await socket.SendAsync(new ArraySegment<byte>(data),WebSocketMessageType.Binary,true,t);}
