 static string ExtractText(Dictionary<string,object> r){object result;if(r==null||!r.TryGetValue("result",out result)||result==null)return "";return ExtractResult(result);}
 static string ExtractResult(object result){var dict=result as Dictionary<string,object>;if(dict!=null){object text;if(dict.TryGetValue("text",out text)&&text!=null)return Convert.ToString(text);object utterances;if(dict.TryGetValue("utterances",out utterances)){var a=utterances as object[];if(a==null)throw new InvalidDataException("utterances 格式无效。");return string.Concat(a.Select(ExtractResult));}throw new InvalidDataException("result 缺少 text 或 utterances。");}var list=result as object[];if(list!=null)return string.Concat(list.Select(ExtractResult));throw new InvalidDataException("result 格式不受支持。");}
 static byte[] Frame(byte kind,byte codec,byte[] body){var p=new byte[8+body.Length];p[0]=0x11;p[1]=kind;p[2]=codec;p[3]=0;Write32(p,4,body.Length);Buffer.BlockCopy(body,0,p,8,body.Length);return p;}static byte[] Gzip(byte[] b){using(var o=new MemoryStream()){using(var z=new GZipStream(o,CompressionMode.Compress,true))z.Write(b,0,b.Length);return o.ToArray();}}static byte[] Unzip(byte[] b,int o,int n,int mode){if(mode!=1){var p=new byte[n];Buffer.BlockCopy(b,o,p,0,n);return p;}using(var i=new MemoryStream(b,o,n))using(var z=new GZipStream(i,CompressionMode.Decompress))using(var x=new MemoryStream()){z.CopyTo(x);return x.ToArray();}}
 static int Read32(byte[] b,int o){return (b[o]<<24)|(b[o+1]<<16)|(b[o+2]<<8)|b[o+3];}static void Write32(byte[] b,int o,int n){b[o]=(byte)(n>>24);b[o+1]=(byte)(n>>16);b[o+2]=(byte)(n>>8);b[o+3]=(byte)n;}
 public void Dispose(){if(stop!=null)stop.Cancel();if(socket!=null){socket.Dispose();socket=null;}if(stop!=null){stop.Dispose();stop=null;}}
}

static class VoiceCorrections {
 sealed class Rule {public string Alias,Word;public bool Ascii;}
 public static string Apply(string text,IEnumerable<VoiceTerm> terms){if(string.IsNullOrEmpty(text))return text;var ascii=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var exact=new Dictionary<string,string>(StringComparer.Ordinal);var blockedAscii=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var blockedExact=new HashSet<string>(StringComparer.Ordinal);foreach(var term in terms??new VoiceTerm[0]){if(term==null||!term.enabled)continue;foreach(var raw in term.aliases??new List<string>()){string alias=(raw??"").Trim();if(alias.Length==0||alias==term.word)continue;bool isAscii=alias.All(c=>c<128&&(char.IsLetterOrDigit(c)||c=='_'));var map=isAscii?ascii:exact;var blocked=isAscii?blockedAscii:blockedExact;string old;if(map.TryGetValue(alias,out old)&&old!=term.word)blocked.Add(alias);else map[alias]=term.word;}}foreach(string key in blockedAscii)ascii.Remove(key);foreach(string key in blockedExact)exact.Remove(key);var rules=ascii.Select(x=>new Rule{Alias=x.Key,Word=x.Value,Ascii=true}).Concat(exact.Select(x=>new Rule{Alias=x.Key,Word=x.Value})).OrderByDescending(x=>x.Alias.Length).ToList();var output=new StringBuilder(text.Length);for(int i=0;i<text.Length;){Rule hit=null;foreach(var rule in rules){if(i+rule.Alias.Length>text.Length)continue;var comparison=rule.Ascii?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal;if(!string.Equals(text.Substring(i,rule.Alias.Length),rule.Alias,comparison))continue;if(rule.Ascii&&((i>0&&AsciiWord(text[i-1]))||(i+rule.Alias.Length<text.Length&&AsciiWord(text[i+rule.Alias.Length]))))continue;hit=rule;break;}if(hit==null){output.Append(text[i]);i++;}else{output.Append(hit.Word);i+=hit.Alias.Length;}}return output.ToString();}
 static bool AsciiWord(char c){return c<128&&(char.IsLetterOrDigit(c)||c=='_');}
}

sealed class VoiceSession:IDisposable {
 internal const int MaxQueuedAudio=32,FlashTimeoutMilliseconds=60000;
 public VoiceState State {get;private set;}public string Preview {get;private set;}public string DeliveryStatus {get;private set;}public event Action<VoiceState,string,double> Changed;
 readonly VoiceOptions options;readonly List<VoiceTerm> terms;readonly object sync=new object();readonly SynchronizationContext ui;
 CancellationTokenSource cancel;DoubaoAsrClient client;WaveInput input;VoiceTarget target;Timer timeout;TaskCompletionSource<bool> finalResult;MemoryStream flashAudio;Task sendTail=Task.FromResult(0);
 int session,stopping,queuedAudio,queuedAudioGeneration,audioSeen,acceptingAudio,acceptingAudioGeneration,acceptingResults,failureSignaled,stopPending;bool delivered;
 public VoiceSession(VoiceOptions o,List<VoiceTerm> t){options=o;terms=t;var context=SynchronizationContext.Current;if(context==null&&Application.Current!=null)context=new System.Windows.Threading.DispatcherSynchronizationContext(Application.Current.Dispatcher);ui=context;State=VoiceState.Idle;}
 bool Current(int id){return Volatile.Read(ref session)==id;}
 void Post(Action action){if(ui!=null&&SynchronizationContext.Current!=ui)ui.Post(x=>action(),null);else action();}
 Task InvokeUi(Func<Task> action){if(ui==null||SynchronizationContext.Current==ui)return action();var completion=new TaskCompletionSource<bool>();ui.Post(async x=>{try{await action();completion.TrySetResult(true);}catch(Exception e){completion.TrySetException(e);}},null);return completion.Task;}
 void Change(VoiceState s,string text=null,double level=0){State=s;if(text!=null)Preview=text;if(s==VoiceState.Delivering)Preview=VoiceCorrections.Apply(Preview,terms);if(Changed!=null)Changed(s,Preview??"",level);}
 internal static async Task RequireFinal(Task final,int timeoutMilliseconds,CancellationToken token){if(final==null)throw new InvalidOperationException("最终识别结果任务不存在。");var completed=await Task.WhenAny(final,Task.Delay(timeoutMilliseconds,token));if(completed!=final)throw new TimeoutException("等待最终识别结果超时。");await final;}
 public Task Start(bool captureTarget){return InvokeUi(()=>StartOnUi(captureTarget));}
 async Task StartOnUi(bool captureTarget){
  if(State!=VoiceState.Idle)return;if(!options.Ready)throw new InvalidOperationException("请先填写豆包语音服务设置。");
  int id=Interlocked.Increment(ref session);Interlocked.Exchange(ref stopping,0);lock(sync){queuedAudio=0;queuedAudioGeneration=id;}Interlocked.Exchange(ref audioSeen,0);Interlocked.Exchange(ref acceptingAudio,0);Interlocked.Exchange(ref acceptingAudioGeneration,id);Interlocked.Exchange(ref acceptingResults,1);Interlocked.Exchange(ref failureSignaled,0);Interlocked.Exchange(ref stopPending,0);delivered=false;Preview="";DeliveryStatus="";sendTail=Task.FromResult(0);finalResult=new TaskCompletionSource<bool>();target=captureTarget?VoiceTarget.Capture():null;cancel=new CancellationTokenSource();Change(VoiceState.Starting);
  try{
   if(options.Backend=="stream"){
    client=new DoubaoAsrClient(options,terms.Where(x=>x.enabled).Select(x=>x.word));
    client.Text+=(text,final)=>Post(()=>{if(!Current(id)||Volatile.Read(ref acceptingResults)==0)return;if(!string.IsNullOrEmpty(text))Preview=text;Change(State,Preview);if(final&&finalResult!=null)finalResult.TrySetResult(true);});
    client.Failed+=e=>Fail(id,e);
    using(var connectTimeout=new CancellationTokenSource(12000))using(var linked=CancellationTokenSource.CreateLinkedTokenSource(cancel.Token,connectTimeout.Token))await client.Connect(linked.Token);
   }else flashAudio=new MemoryStream();
   if(!Current(id))return;input=new WaveInput();Interlocked.Exchange(ref acceptingAudio,1);input.Level+=v=>Post(()=>{if(Current(id))Change(State,null,v);});input.Data+=b=>OnAudio(id,b);input.Start();timeout=new Timer(x=>Post(async()=>await Stop()),null,TimeSpan.FromSeconds(Math.Max(10,Math.Min(300,options.MaxSeconds))),Timeout.InfiniteTimeSpan);Change(VoiceState.Listening);if(Volatile.Read(ref stopPending)!=0)await StopOnUi(id);
  }catch(Exception){if(Current(id)){CloseGeneration(id);Cleanup();Change(VoiceState.Idle);}throw;}
 }
 void OnAudio(int id,byte[] bytes){
  if(!Current(id)||Volatile.Read(ref acceptingAudio)==0||bytes==null||bytes.Length==0)return;Interlocked.Exchange(ref audioSeen,1);
  if(options.Backend!="stream"){lock(sync){if(Current(id)&&flashAudio!=null)flashAudio.Write(bytes,0,bytes.Length);}return;}
  Task next;CancellationToken token;DoubaoAsrClient activeClient;bool overflow=false;lock(sync){if(!Current(id)||queuedAudioGeneration!=id||cancel==null||client==null)return;if(++queuedAudio>MaxQueuedAudio){queuedAudio--;overflow=true;next=null;token=CancellationToken.None;activeClient=null;}else{token=cancel.Token;activeClient=client;next=SendAfter(sendTail,activeClient,bytes,token,id);sendTail=next;}}
  if(overflow){Fail(id,"语音网络发送过慢，请检查连接后重试。");return;}
  next.ContinueWith(t=>Fail(id,t.Exception.GetBaseException().Message),CancellationToken.None,TaskContinuationOptions.OnlyOnFaulted,TaskScheduler.Default);
 }
 async Task SendAfter(Task previous,DoubaoAsrClient activeClient,byte[] bytes,CancellationToken token,int id){try{await previous;if(Current(id)){token.ThrowIfCancellationRequested();await activeClient.SendAudio(bytes,false,token);}}finally{ReleaseQueuedAudio(id);}}
 void ReleaseQueuedAudio(int id){lock(sync){if(queuedAudioGeneration==id&&queuedAudio>0)queuedAudio--;}}
 void StopAcceptingAudio(int id){if(Current(id)&&Volatile.Read(ref acceptingAudioGeneration)==id)Interlocked.Exchange(ref acceptingAudio,0);}
 public Task Stop(){return InvokeUi(StopRequestedOnUi);}
 Task StopRequestedOnUi(){if(State==VoiceState.Starting){Interlocked.Exchange(ref stopPending,1);Interlocked.Exchange(ref stopping,1);return Task.FromResult(0);}if(State!=VoiceState.Listening||Interlocked.CompareExchange(ref stopping,1,0)!=0)return Task.FromResult(0);return StopOnUi(Volatile.Read(ref session));}
 async Task StopOnUi(int id){
  if(!Current(id))return;Change(VoiceState.Finalizing);var activeInput=input;input=null;
  try{
   if(activeInput!=null)await Task.Run(()=>{activeInput.StopAndDrain();activeInput.Dispose();});StopAcceptingAudio(id);if(!Current(id))return;
   if(Volatile.Read(ref audioSeen)==0){if(CloseGeneration(id)){Cleanup();Change(VoiceState.Idle,"");}return;}
   var sessionCancel=cancel;if(sessionCancel==null)throw new OperationCanceledException();
   if(options.Backend=="stream"){Task pending;Task final;DoubaoAsrClient activeClient;lock(sync){pending=sendTail;final=finalResult==null?null:finalResult.Task;activeClient=client;}await pending;EnsureDeliveryActive(id,sessionCancel.Token);await activeClient.SendAudio(new byte[0],true,sessionCancel.Token);EnsureDeliveryActive(id,sessionCancel.Token);await RequireFinal(final,10000,sessionCancel.Token);EnsureDeliveryActive(id,sessionCancel.Token);}
   else{byte[] pcm;lock(sync)pcm=flashAudio==null?new byte[0]:flashAudio.ToArray();try{using(var flashTimeout=new CancellationTokenSource(FlashTimeoutMilliseconds))using(var linked=CancellationTokenSource.CreateLinkedTokenSource(sessionCancel.Token,flashTimeout.Token))Preview=await new FlashAsrClient(options,terms.Where(x=>x.enabled).Select(x=>x.word).ToList()).Recognize(pcm,linked.Token);EnsureDeliveryActive(id,sessionCancel.Token);}catch(OperationCanceledException){if(!sessionCancel.IsCancellationRequested)throw new TimeoutException("豆包语音识别请求超时。");throw;}}
   EnsureDeliveryActive(id,sessionCancel.Token);if(string.IsNullOrWhiteSpace(Preview))throw new InvalidOperationException("没有识别到语音。");Interlocked.Exchange(ref acceptingResults,0);Change(VoiceState.Delivering);string finalText=Preview;VoiceTarget destination=target;bool pasted=await Deliver(id,destination,finalText,sessionCancel.Token);EnsureDeliveryActive(id,sessionCancel.Token);if(!CloseGeneration(id)||delivered)return;delivered=true;DeliveryStatus=pasted?"已输入并复制":"已复制，请手动粘贴";Cleanup();try{VoiceData.AddHistory(finalText,"final",options);}catch{DeliveryStatus+="；历史保存失败";}Change(VoiceState.Idle,finalText);
  }catch(FlashAsrException e){if(e.StatusCode=="20000003")FinishNoSpeech(id);else Fail(id,e.Message);}catch(OperationCanceledException){if(Current(id))Fail(id,"语音识别已取消。");}catch(Exception e){Fail(id,e.Message);}finally{if(activeInput!=null){try{activeInput.Dispose();}catch{}}StopAcceptingAudio(id);}
 }
 void EnsureDeliveryActive(int id,CancellationToken token){token.ThrowIfCancellationRequested();if(!Current(id))throw new OperationCanceledException();}
 async Task<bool> Deliver(int id,VoiceTarget destination,string text,CancellationToken token){
  EnsureDeliveryActive(id,token);if(ui!=null&&SynchronizationContext.Current!=ui){bool result=false;await InvokeUi(async()=>{result=await Deliver(id,destination,text,token);});EnsureDeliveryActive(id,token);return result;}
  bool pasted=destination!=null&&await destination.Paste(text,token);EnsureDeliveryActive(id,token);if(pasted)return true;for(int i=0;i<6;i++){EnsureDeliveryActive(id,token);bool retry=false;try{Clipboard.SetText(text);return false;}catch(COMException){retry=true;}if(retry&&i<5){await Task.Delay(80,token);EnsureDeliveryActive(id,token);}}throw new InvalidOperationException("剪贴板正被占用，未能自动粘贴。");
 }
 bool CloseGeneration(int id){return Interlocked.CompareExchange(ref session,id+1,id)==id;}
 void FinishNoSpeech(int id){Post(()=>{if(!CloseGeneration(id))return;Cleanup();DeliveryStatus="";Change(VoiceState.Idle,"没有识别到语音，请再试一次。");});}
 public void Cancel(){int id=Volatile.Read(ref session);Interlocked.CompareExchange(ref session,id+1,id);var activeCancel=cancel;if(activeCancel!=null)try{activeCancel.Cancel();}catch(ObjectDisposedException){}Post(()=>{Cleanup();Preview="";DeliveryStatus="";Change(VoiceState.Idle);});}
 void Fail(int id,string error){if(!Current(id)||Interlocked.CompareExchange(ref failureSignaled,1,0)!=0)return;Post(()=>FinishFailure(id,error));}
 void FinishFailure(int id,string error){if(!CloseGeneration(id))return;string draft=Preview;Cleanup();DeliveryStatus="";if(!string.IsNullOrWhiteSpace(draft))try{VoiceData.AddHistory(draft,"incomplete",options);}catch{error+="；未能保存未完成草稿";}Change(VoiceState.Error,error);Change(VoiceState.Idle,error);}
 void Cleanup(){Interlocked.Exchange(ref acceptingAudio,0);Interlocked.Exchange(ref acceptingAudioGeneration,0);Interlocked.Exchange(ref acceptingResults,0);if(timeout!=null){timeout.Dispose();timeout=null;}if(input!=null){try{input.Cancel();input.Dispose();}catch{}input=null;}if(cancel!=null){try{cancel.Cancel();}catch{}cancel.Dispose();cancel=null;}if(client!=null){client.Dispose();client=null;}lock(sync){if(flashAudio!=null){flashAudio.Dispose();flashAudio=null;}sendTail=Task.FromResult(0);queuedAudio=0;queuedAudioGeneration=0;}if(finalResult!=null){finalResult.TrySetCanceled();finalResult=null;}target=null;Interlocked.Exchange(ref stopping,0);}
 public void Dispose(){Cancel();}
}
